<?php require_once '../config/session.php'; puede_cuidar(); require_once '../config/db.php';
function estado_label($e){ $map=['administrado'=>'Administrado','realizada'=>'Realizada','no_pudo'=>'No se pudo','no_dado'=>'No administrado','no_realizada'=>'No realizada','pendiente'=>'Pendiente',''=>'Pendiente',null=>'Pendiente']; return $map[$e] ?? $e; }
function estado_class($e){ if($e==='administrado'||$e==='realizada') return 'estado-ok'; if($e==='no_pudo') return 'estado-alerta'; if($e==='no_dado'||$e==='no_realizada') return 'estado-problema'; return 'estado-pendiente'; }
if(isset($_GET['accion']) && es_admin()){ $pdo->prepare('UPDATE residentes SET estado=? WHERE id_residente=?')->execute([$_GET['accion'],$_GET['id']]); header('Location: listar.php'); exit; }
if(isset($_GET['eliminar']) && es_admin()){ $pdo->prepare('UPDATE residentes SET eliminado=1 WHERE id_residente=?')->execute([$_GET['eliminar']]); $pdo->prepare("INSERT INTO papelera(tabla,registro_id,accion,usuario) VALUES('residentes',?,'eliminado',?)")->execute([$_GET['eliminar'],$_SESSION['usuario']['email']]); header('Location: listar.php'); exit; }
include '../config/menu.php';
if(isset($_GET['ver'])){
 $st=$pdo->prepare('SELECT r.*,h.numero habitacion,h.sector,h.piso,h.cama,h.estado estado_habitacion FROM residentes r LEFT JOIN habitaciones h ON h.id_habitacion=r.id_habitacion WHERE r.id_residente=?'); $st->execute([$_GET['ver']]); $r=$st->fetch();
 $med=$pdo->prepare("SELECT mr.*,m.nombre med,m.presentacion,rec.diagnostico,rec.fecha_inicio r_inicio,rec.fecha_fin r_fin,rec.foto_receta FROM medicacion_residente mr JOIN medicamentos m ON m.id_medicamento=mr.id_medicamento LEFT JOIN recetas_medicas rec ON rec.id_receta=mr.id_receta WHERE mr.id_residente=? AND mr.eliminado=0 ORDER BY rec.fecha_inicio DESC,mr.horario"); $med->execute([$r['id_residente']]); $med=$med->fetchAll();
 $hist=$pdo->prepare("SELECT am.*,m.nombre med,m.presentacion,u.nombre cuidadora,mr.dosis,mr.horario,rec.diagnostico FROM administracion_medicacion am JOIN medicamentos m ON m.id_medicamento=am.id_medicamento LEFT JOIN usuarios u ON u.id_usuario=am.id_cuidadora_usuario LEFT JOIN medicacion_residente mr ON mr.id_plan=am.id_plan LEFT JOIN recetas_medicas rec ON rec.id_receta=mr.id_receta WHERE am.id_residente=? AND am.fecha_hora >= DATE_SUB(NOW(), INTERVAL 7 DAY) ORDER BY am.fecha_hora DESC"); $hist->execute([$r['id_residente']]); $hist=$hist->fetchAll(); ?>
<h1>Ficha completa del residente</h1>
<div class="card detail-grid">
 <div class="info-box"><?php if($r['foto']):?><img class="photo" src="<?=BASE_URL.'/'.$r['foto']?>"><br><?php endif;?><b><?=$r['nombre'].' '.$r['apellido']?></b></div>
 <div class="info-box"><b>DNI</b><br><?=$r['dni']?></div>
 <div class="info-box"><b>Fecha nacimiento</b><br><?=$r['fecha_nacimiento']?></div>
 <div class="info-box"><b>Habitación</b><br><?= $r['habitacion'] ? 'Hab. '.$r['habitacion'].' · '.$r['sector'].' · '.$r['piso'].' · '.$r['cama'] : 'Sin asignar' ?><br><span class="small">Estado: <?=$r['estado_habitacion']?:'-'?></span></div>
 <div class="info-box"><b>Movilidad autónoma</b><br><?=$r['movilidad_autonoma']?'Sí':'No'?></div>
 <div class="info-box"><b>Familiar</b><br><?=$r['contacto_familiar']?> · <?=$r['telefono_familiar']?></div>
 <div class="info-box"><b>Estado</b><br><span class="pill estado-<?=$r['estado']?>"><?=$r['estado']?></span></div>
