</div>
<h2>Medicamentos y recetas del residente</h2><table><tr><th>Tratamiento / receta</th><th>Medicamento</th><th>Dosis</th><th>Horario</th><th>Inicio</th><th>Vencimiento</th><th>Indicación</th></tr><?php foreach($med as $m):?><tr><td><?=htmlspecialchars($m['diagnostico']?:'-')?><?php if($m['foto_receta']):?><br><a class="btn blue" target="_blank" href="<?=BASE_URL.'/'.$m['foto_receta']?>">Ver foto receta</a><?php endif;?></td><td><?=$m['med']?> <?=$m['presentacion']?></td><td><?=$m['dosis']?></td><td><b><?=$m['horario']?></b></td><td><?=$m['fecha_inicio']?></td><td><?=$m['fecha_fin']?:'Permanente'?></td><td><?=$m['indicacion']?></td></tr><?php endforeach;?></table>
<h2>Historial de medicación - últimos 7 días</h2><table><tr><th>Fecha y hora</th><th>Medicamento</th><th>Dosis</th><th>Tratamiento</th><th>Estado</th><th>Quién registró</th><th>Motivo</th></tr><?php foreach($hist as $h):?><tr><td><?=$h['fecha_hora']?></td><td><?=$h['med']?> <?=$h['presentacion']?></td><td><?=$h['dosis']?></td><td><?=htmlspecialchars($h['diagnostico']?:'-')?></td><td><div class="estado-cuadro <?=estado_class($h['estado_adm'])?>"><?=estado_label($h['estado_adm'])?></div></td><td><?=$h['cuidadora']?:'-'?></td><td><?=htmlspecialchars($h['observaciones'])?></td></tr><?php endforeach;?></table><br><a class="btn gray" href="listar.php">Volver</a>
<?php include '../config/footer.php'; exit; }
