<table><tr><th>Foto</th><th>Nombre</th><th>Habitación</th><th>DNI</th><th>Familiar</th><th>Datos médicos</th><th>Estado</th><th>Acciones</th></tr><?php foreach($rows as $r):?><tr><td><?php if($r['foto']):?><img class="foto" src="<?=BASE_URL.'/'.$r['foto']?>"><?php endif;?></td><td><?=htmlspecialchars($r['nombre'].' '.$r['apellido'])?></td><td><?= $r['habitacion'] ? 'Hab. '.$r['habitacion'].'<br><span class="small">'.$r['sector'].'</span>' : 'Sin asignar' ?></td><td><?=$r['dni']?></td><td><?=htmlspecialchars($r['contacto_familiar'])?><br><span class="small"><?=$r['telefono_familiar']?></span></td><td><?=htmlspecialchars($r['obs_medicas'])?></td><td><span class="pill estado-<?=$r['estado']?>"><?=$r['estado']?></span></td><td><a class="btn blue" href="?ver=<?=$r['id_residente']?>">Ver todo</a><?php if(es_admin()):?><a class="btn" href="crear.php?id=<?=$r['id_residente']?>">Modificar</a><a class="btn green" href="?accion=activo&id=<?=$r['id_residente']?>">Activar</a><a class="btn orange" href="?accion=pausado&id=<?=$r['id_residente']?>">Pausar</a><a class="btn gray" href="?accion=baja&id=<?=$r['id_residente']?>">Baja</a><a class="btn red" href="?eliminar=<?=$r['id_residente']?>">Papelera</a><?php endif;?></td></tr><?php endforeach;?></table><?php include '../config/footer.php'; ?>
